<?php require 'bootstrap.php';if(user()){header('Location: channels.php');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=trim((string)($_POST['identity']??''));$pass=(string)($_POST['password']??'');$q=db()->prepare("SELECT * FROM ls_users WHERE status='active' AND (username_normalized=? OR email=?) LIMIT 1");$q->execute([norm_nick($id),$id]);$u=$q->fetch();if($u && password_verify($pass,(string)$u['password_hash'])){session_regenerate_id(true);$_SESSION['uid']=(int)$u['id'];header('Location: channels.php');exit;}$err='Login nicht korrekt.';}$title='Login';require 'header.php';?><section class="panel narrow"><span>ACCOUNT LOGIN</span><h1>Einloggen</h1><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Nickname oder E-Mail<input name="identity" required autocomplete="username"></label><label>Passwort<input name="password" type="password" required autocomplete="current-password"></label><button>Login</button></form><p class="hint">IRC-Clients bleiben normal nutzbar. Account-Verwaltung erfolgt hier im Web.</p></section><?php require 'footer.php';?>
